<?php
$file = "/home/u747826271/domains/eurotaxisystem.site/public_html/resources/views/partials/chat-drawer.blade.php";
$content = file_get_contents($file);

$pickerStart = strpos($content, "<div id=\"chatReactionPicker\"");
$pickerEnd = strpos($content, "</div>\n  <script>", $pickerStart);
if ($pickerEnd === false) {
    // maybe it is the old picker format
    $pickerEnd = strpos($content, "</button>\n  </div>", $pickerStart) + 18;
} else {
    // new picker format with script
    $pickerEnd = strpos($content, "</script>", $pickerStart) + 9;
}

$newPickerB64 = "";
$newPicker = base64_decode($newPickerB64);

$content = substr_replace($content, $newPicker, $pickerStart, $pickerEnd - $pickerStart);

file_put_contents($file, $content);
echo "Fixed picker!";

